logger = logging.getLogger(__name__)

# GCU400 Fixed Grid: 24 SIPs, 2 CTAs per SIP cap from the arctanh_/lgamma_
# family measurements (grid > 48 only adds CTA overhead on this backend).
NUM_SIPS = 24
LN2 = 0.6931471805599453
LOG_PI = 1.1447298858494002


@triton.jit
def _lgamma_stirling(x, SHIFT_THRESHOLD: tl.constexpr):
    # fp32 lgamma via reflection + shift-to->=SHIFT_THRESHOLD + 3-term
    # Stirling asymptotics, copied from the GCU400 lgamma/mvlgamma family
    # where it is validated against CPU double (atol=2e-5 / rtol=1.3e-6)
    # and is 2-25x faster than the libdevice extern, which also degrades
    # 7.7x on 16-bit-wide pipelines.  The reflection arm guarantees
    # y > 0.5, so SHIFT_THRESHOLD=4 shift steps always reach y >= 4.5
    # where the omitted O(1/(1680 y^7)) term is below fp32 eps.
    reflect = x < 0.5
    y = tl.where(reflect, 1.0 - x, x)
    t = 1.0
    for _ in tl.static_range(SHIFT_THRESHOLD):
        m = y < SHIFT_THRESHOLD * 1.0
        t = tl.where(m, t * y, t)
        y = tl.where(m, y + 1.0, y)
    logy = tl.log(y)
    # 1/y via rsqrt(y*y): same value for y > 0 (series term is only r/12),
    # and it avoids the divide that pushes the 16-bit pipeline onto a
    # slower codegen path on GCU400.
    r = tl.math.rsqrt(y * y)
    r2 = r * r
    series = r * (
        0.08333333333333333 - r2 * (0.002777777777777778 - r2 * 0.0007936507936507937)
    )
    res = (y - 0.5) * logy - y + 0.9189385332046727 + series - tl.log(t)
    # Reflection for x < 0.5: lgamma(x) = log(pi) - log|sin(pi x)| -
    # lgamma(1-x).  `reduced` is in [-0.5, 0.5], so |angle| <= pi/2 and a
    # 7-term odd Taylor for sin suffices; the 2^64 pre-scaling keeps
    # log|sin| finite for subnormal |sin|.
    reduced = x - tl.floor(x + 0.5)
    angle = 3.141592653589793 * reduced
    angle2 = angle * angle
    sin_poly = 1.0 - angle2 * (
        0.16666666666666666
        - angle2
        * (
            0.008333333333333333
            - angle2
            * (
                0.0001984126984126984
                - angle2 * (2.7557319223985893e-06 - angle2 * 2.505210838544172e-08)
            )
        )
    )
    sin_pi_x = angle * sin_poly
    log_sin = tl.log(tl.abs(sin_pi_x) * 18446744073709551616.0) - 44.3614195558365
    reflected = 1.1447298858494002 - log_sin - res
    result = tl.where(reflect, reflected, res)
    # Gamma's poles (0 and the negative integers) and +-inf map to +inf;
    # NaN propagates through the arithmetic.  The pole test reuses
    # `reduced` (x - round(x) == 0 iff x is an exact integer).  For
    # |x| >= 2^23 the fp32 addition x + 0.5 rounds FIRST (ulp >= 1), so
    # odd integers in [2^23, 2^24) get reduced == +-1 and the pole is
    # missed; every representable fp32 value with |x| >= 2^23 is an
    # integer, and lgamma's poles are the non-positive ones, so the
    # constant comparison closes the gap without a second floor.
    is_pole = (x <= 0.0) & ((reduced == 0.0) | (x <= -8388608.0))
    result = tl.where(is_pole | (tl.abs(x) == float("inf")), float("inf"), result)
    return result


@triton.jit
def _mvlgamma_sum(
    x_f32,
    M: tl.constexpr,
    IS_ODD: tl.constexpr,
    LIN: tl.constexpr,
    CONST: tl.constexpr,
    SHIFT_THRESHOLD: tl.constexpr,
):
    # mvlgamma(x, p) = p*(p-1)/4*log(pi) + sum_{k=0}^{p-1} lgamma(x - k/2).
    # Consecutive even/odd terms are paired through the Legendre
    # duplication formula lgamma(z) + lgamma(z+1/2) = (1-2z)*ln2 +
    # ln(pi)/2 + lgamma(2z) with z = x-j-1/2, an exact identity over the
    # whole domain (poles of either pair member map to poles of
    # lgamma(2z)).  p terms collapse to M pairs plus one leftover term for
    # odd p, leaving the LIN*x + CONST epilogue with host-precomputed
    # scalars (the enflame frontend does not fold constexpr //
    # expressions, so all p-derived values come from the wrapper).
    acc = tl.zeros_like(x_f32)
    for j in tl.static_range(M):
        acc += _lgamma_stirling(2.0 * x_f32 - (2 * j + 1), SHIFT_THRESHOLD)
    if IS_ODD:
        acc += _lgamma_stirling(x_f32 - M, SHIFT_THRESHOLD)
    total = acc + LIN * x_f32 + CONST
    # mvlgamma(+-inf, p) = +inf (aten semantics: lgamma(+-inf) = +inf for
    # every term).  At the literal limits the duplication epilogue
    # degenerates first: x = +inf hits inf - inf for p >= 2 and 0*inf for
    # p == 1; x = -inf is only correct for p >= 2 (p == 1 has LIN == 0 and
    # 0*-inf is NaN), so pin both infinities explicitly.  NaN inputs fall
    # through the comparison untouched.
    return tl.where(tl.abs(x_f32) == float("inf"), float("inf"), total)


@libentry()
@triton.jit(do_not_specialize=["n_elements"])
def mvlgamma_kernel_(
    x_ptr,
    n_elements,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    M: tl.constexpr,
    IS_ODD: tl.constexpr,
    LIN: tl.constexpr,
    CONST: tl.constexpr,
    WIDE: tl.constexpr,
):
    pid = tl.program_id(axis=0)
    num_pids = tl.num_programs(0)
    num_blocks = (n_elements + BLOCK - 1) // BLOCK
    for block_id in tl.range(pid, num_blocks, num_pids):
        # WIDE: the grid cap no longer bounds the covered offset domain, so
        # element offsets past int32 (n_elements > 2**31 - BLOCK) must be
        # computed in int64 to avoid wrap-around loads/stores.
        if WIDE:
            off = block_id.to(tl.int64) * BLOCK + tl.arange(0, BLOCK)
        else:
            off = block_id * BLOCK + tl.arange(0, BLOCK)
        if EVEN:
            x = tl.load(x_ptr + off)
            result = _mvlgamma_sum(x.to(tl.float32), M, IS_ODD, LIN, CONST, 4)
            tl.store(x_ptr + off, result.to(x_ptr.dtype.element_ty))
        else:
            mask = off < n_elements
            x = tl.load(x_ptr + off, mask=mask, other=0.0)
            result = _mvlgamma_sum(x.to(tl.float32), M, IS_ODD, LIN, CONST, 4)
            tl.store(x_ptr + off, result.to(x_ptr.dtype.element_ty), mask=mask)


def _choose_block(n):
    if n <= 4096:
        return triton.next_power_of_2(max(min(n, 1024), 1))
    # 2048/num_warps=4 is the lgamma-family optimum on GCU400 (fixed grid,
    # 48 CTAs: fp16 512M elements 16.07 ms vs 19.23 ms at BLOCK=1024 and
    # 20.82 ms at BLOCK=4096); the BLOCK x num_warps surface is flat
    # (+-0.3%) for this compute-dominated body.
    return 2048


def mvlgamma_(*args, **kwargs):
    logger.debug("GEMS_ENFLAME MVLGAMMA_")
