    p = args[1] if len(args) > 1 else kwargs.get("p", 1)

    if not isinstance(x, torch.Tensor):
        raise TypeError("mvlgamma_ expects a torch.Tensor as the first argument")

    if not isinstance(p, int) or p < 1:
        raise ValueError("p must be a positive integer")

    # Limit p to 12 (the aten contract for mvlgamma_ preserved from the
    # baseline; the duplication sum serves any p, but the registered op
    # keeps the baseline bound).
